using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using StackExchange.Redis.Extensions.Core.Abstractions;
using TwitchLib.Api;

namespace Infrastructure.Services
{
    // The bot's own chat (IRC) token, shared by every channel connection.
    // Seeded once from the bot_access_token/bot_refresh_token config vars, then kept in Redis
    // and refreshed before it expires, so it never has to be regenerated by hand.
    public class BotToken
    {
        public string AccessToken { get; set; } = string.Empty;
        public string RefreshToken { get; set; } = string.Empty;
        public DateTimeOffset ExpiresAt { get; set; }
        public DateTimeOffset RefreshedAt { get; set; }

        // SHA-256 of the bot_refresh_token config var this token was seeded from. When the
        // config var changes (a new token was issued by hand), the stored token is replaced.
        public string? Seed { get; set; }
    }

    public record RefreshedToken(string AccessToken, string RefreshToken, int ExpiresIn);

    public interface IBotTokenStore
    {
        Task<BotToken?> Get();
        Task Save(BotToken token);
    }

    public class RedisBotTokenStore : IBotTokenStore
    {
        private const string Key = "bottoken";
        private readonly IRedisClient _redisClient;

        public RedisBotTokenStore(IRedisClient redisClient)
        {
            _redisClient = redisClient;
        }

        public Task<BotToken?> Get() => _redisClient.Db0.GetAsync<BotToken>(Key);

        public Task Save(BotToken token) => _redisClient.Db0.AddAsync(Key, token);
    }

    public interface ITwitchTokenRefresher
    {
        Task<RefreshedToken> Refresh(string refreshToken);
    }

    public class TwitchTokenRefresher : ITwitchTokenRefresher
    {
        private readonly IConfiguration _configuration;

        public TwitchTokenRefresher(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public async Task<RefreshedToken> Refresh(string refreshToken)
        {
            var twitchApi = new TwitchAPI();
            var response = await twitchApi.Auth.RefreshAuthTokenAsync(refreshToken, _configuration["twitch_client_secret"], _configuration["twitch_client_id"]);

            return new RefreshedToken(response.AccessToken, response.RefreshToken, response.ExpiresIn);
        }
    }

    public class BotTokenService : IBotTokenService
    {
        // refresh this long before the token actually expires
        private static readonly TimeSpan RefreshMargin = TimeSpan.FromMinutes(15);
        // a forced refresh (after a failed login) is skipped if the token was just refreshed,
        // so several channel connections failing at once only refresh it once
        private static readonly TimeSpan ForcedRefreshCooldown = TimeSpan.FromMinutes(1);

        private readonly IBotTokenStore _store;
        private readonly ITwitchTokenRefresher _refresher;
        private readonly IConfiguration _configuration;
        private readonly ILogger<BotTokenService> _logger;
        private readonly TimeProvider _time;
        private readonly SemaphoreSlim _lock = new(1, 1);
        private BotToken? _token;

        public BotTokenService(IBotTokenStore store, ITwitchTokenRefresher refresher, IConfiguration configuration, ILogger<BotTokenService> logger, TimeProvider time)
        {
            _store = store;
            _refresher = refresher;
            _configuration = configuration;
            _logger = logger;
            _time = time;
        }

        public async Task<string?> GetAccessToken(bool forceRefresh = false)
        {
            await _lock.WaitAsync();
            try
            {
                var seedRefreshToken = _configuration["bot_refresh_token"];
                var seed = string.IsNullOrEmpty(seedRefreshToken) ? null : Hash(seedRefreshToken);

                _token ??= await _store.Get();

                if (seed != null && _token?.Seed != seed)
                {
                    _logger.LogInformation("[bottoken] Seeding bot token from config");
                    _token = new BotToken
                    {
                        AccessToken = _configuration["bot_access_token"] ?? string.Empty,
                        RefreshToken = seedRefreshToken!,
                        ExpiresAt = DateTimeOffset.MinValue,
                        Seed = seed
                    };
                }

                // no refresh token anywhere: fall back to the plain config token (expires, can't be renewed)
                if (_token == null)
                    return _configuration["bot_access_token"];

                var now = _time.GetUtcNow();
                var expiring = now + RefreshMargin >= _token.ExpiresAt;
                var forced = forceRefresh && now - _token.RefreshedAt >= ForcedRefreshCooldown;

                if (expiring || forced)
                {
                    try
                    {
                        var refreshed = await _refresher.Refresh(_token.RefreshToken);

                        _token = new BotToken
                        {
                            AccessToken = refreshed.AccessToken,
                            RefreshToken = refreshed.RefreshToken,
                            ExpiresAt = now.AddSeconds(refreshed.ExpiresIn),
                            RefreshedAt = now,
                            Seed = _token.Seed
                        };

                        await _store.Save(_token);

                        _logger.LogInformation($"[bottoken] Bot token refreshed, expires at {_token.ExpiresAt:u}");
                    }
                    catch (Exception e)
                    {
                        // keep using the current token; it may still be valid
                        _logger.LogError(e, "[bottoken] Error refreshing bot token");
                    }
                }

                return _token.AccessToken;
            }
            finally
            {
                _lock.Release();
            }
        }

        private static string Hash(string value)
        {
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
        }
    }

    public interface IBotTokenService
    {
        Task<string?> GetAccessToken(bool forceRefresh = false);
    }
}
